          if (mode === 'unread') {{
            item.style.display = item.getAttribute('data-room-filter') === 'unread' ? 'flex' : 'none';
          }} else {{
            item.style.display = 'flex';
          }}
        }});
      }};

      window.s1OpenChatRoom = function(roomId, pushHash = true) {{
