    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(path.suffix + ".tmp065")
    with open(tmp, "w", encoding="utf-8", errors="strict") as f:
        f.write(content)
    os.replace(tmp, path)

